class Solution {
public:
    int targetR = -1, targetC = -1;
    char fwd[4] = {'U', 'D', 'L', 'R'};
    char bwd[4] = {'D', 'U', 'R', 'L'};
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};
    map<pair<int, int>, int> grid;

    void dfs(int r, int c, GridMaster& master) {
        if (master.isTarget()) {
            targetR = r; targetC = c;
        }
        grid[{r, c}] = 1;
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i], nc = c + dc[i];
            if (!grid.count({nr, nc})) {
                if (master.canMove(fwd[i])) {
                    master.move(fwd[i]);
                    dfs(nr, nc, master);
                    master.move(bwd[i]);
                } else {
                    grid[{nr, nc}] = 0;
                }
            }
        }
    }
    int findShortestPath(GridMaster& master) {
        dfs(0, 0, master);
        if (targetR == -1 && targetC == -1) return -1;
        queue<tuple<int, int, int>> q;
        q.push({0, 0, 0});
        set<pair<int, int>> visited;
        visited.insert({0, 0});
        while (!q.empty()) {
            auto [r, c, d] = q.front(); q.pop();
            if (r == targetR && c == targetC) return d;
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i], nc = c + dc[i];
                if (grid[{nr, nc}] == 1 && !visited.count({nr, nc})) {
                    visited.insert({nr, nc});
                    q.push({nr, nc, d + 1});
                }
            }
        }
        return -1;
    }
};

class Solution {
    private int targetR = -1, targetC = -1;
    private char[] fwd = {'U', 'D', 'L', 'R'};
    private char[] bwd = {'D', 'U', 'R', 'L'};
    private int[] dr = {-1, 1, 0, 0};
    private int[] dc = {0, 0, -1, 1};
    private Map<String, Integer> grid = new HashMap<>();

    private void dfs(int r, int c, GridMaster master) {
        if (master.isTarget()) {
            targetR = r; targetC = c;
        }
        grid.put(r + "," + c, 1);
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i], nc = c + dc[i];
            String key = nr + "," + nc;
            if (!grid.containsKey(key)) {
                if (master.canMove(fwd[i])) {
                    master.move(fwd[i]);
                    dfs(nr, nc, master);
                    master.move(bwd[i]);
                } else {
                    grid.put(key, 0);
                }
            }
        }
    }
    public int findShortestPath(GridMaster master) {
        dfs(0, 0, master);
        if (targetR == -1 && targetC == -1) return -1;
        Queue<int[]> q = new ArrayDeque<>();
        q.add(new int[]{0, 0, 0});
        Set<String> visited = new HashSet<>();
        visited.add("0,0");
        while (!q.isEmpty()) {
            int[] curr = q.poll();
            int r = curr[0], c = curr[1], d = curr[2];
            if (r == targetR && c == targetC) return d;
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i], nc = c + dc[i];
                String key = nr + "," + nc;
                if (grid.getOrDefault(key, 0) == 1 && !visited.contains(key)) {
                    visited.add(key);
                    q.add(new int[]{nr, nc, d + 1});
                }
            }
        }
        return -1;
    }
}

var findShortestPath = function(master) {
    let target = null;
    const grid = new Map();
    const dirs = [
        ['U', 'D', -1, 0],
        ['D', 'U', 1, 0],
        ['L', 'R', 0, -1],
        ['R', 'L', 0, 1]
    ];
    function dfs(r, c) {
        if (master.isTarget()) target = [r, c];
        grid.set(`${r},${c}`, 1);
        for (const [fwd, bwd, dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            const key = `${nr},${nc}`;
            if (!grid.has(key)) {
                if (master.canMove(fwd)) {
                    master.move(fwd);
                    dfs(nr, nc);
                    master.move(bwd);
                } else {
                    grid.set(key, 0);
                }
            }
        }
    }
    dfs(0, 0);
    if (!target) return -1;
    const q = [[0, 0, 0]];
    const visited = new Set(['0,0']);
    while (q.length > 0) {
        const [r, c, d] = q.shift();
        if (r === target[0] && c === target[1]) return d;
        for (const [, , dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            const key = `${nr},${nc}`;
            if (grid.get(key) === 1 && !visited.has(key)) {
                visited.add(key);
                q.push([nr, nc, d + 1]);
            }
        }
    }
    return -1;
};
